<?php
namespace App\Http\Controllers;
use App\Models\{Communication,Donation,Member,PastoralNote};use Illuminate\Http\{RedirectResponse,Request};use Illuminate\Validation\Rule;
class MemberActivityController extends Controller {
 public function donation(Request $r,Member $member):RedirectResponse{abort_unless((bool) config('features.donations'), 404);$this->authorize('update',$member);$d=$r->validate(['donation_date'=>'required|date','amount'=>'required|numeric|min:0.01','currency'=>'required|string|size:3','fund'=>'required|string|max:64','payment_method'=>'nullable|string|max:32','status'=>['required',Rule::in(['pending','completed','failed','refunded'])],'receipt_number'=>'nullable|string|max:100|unique:donations,receipt_number','notes'=>'nullable|string|max:2000']);$member->donations()->create($d);return back()->with('success','Donation recorded.');}
 public function communication(Request $r,Member $member):RedirectResponse{$this->authorize('update',$member);$d=$r->validate(['type'=>'required|string|max:32','direction'=>['required',Rule::in(['inbound','outbound'])],'subject'=>'nullable|string|max:255','message'=>'nullable|string|max:5000','sent_at'=>'nullable|date','status'=>['required',Rule::in(['draft','sent','delivered','failed'])],'summary'=>'nullable|string|max:1000']);$member->communications()->create([...$d,'created_by'=>$r->user()->id]);return back()->with('success','Communication recorded.');}
 public function pastoralNote(Request $r,Member $member):RedirectResponse{$this->authorize('create',PastoralNote::class);$d=$r->validate(['note_date'=>'required|date','category'=>'required|string|max:48','content'=>'required|string|max:10000','follow_up_status'=>['required',Rule::in(['not_required','pending','completed'])],'follow_up_due_date'=>'nullable|date','confidential'=>'boolean']);$member->pastoralNotes()->create([...$d,'author_id'=>$r->user()->id]);return back()->with('success','Confidential pastoral note saved.');}
}
